hydrate(db);const migration=migrate(db);db.jobs??=[];db.jobEvents??=[];db.artifacts??=[];ensureIdentitySeed(db);if(migration.applied.length)persist(db);const artifacts=new ArtifactStore({metadata:db.artifacts});const timeSeries=new TimeSeriesStore({root:process.env.AUTOFORGE_TIMESERIES_DIR||path.join(process.env.AUTOFORGE_DATA_DIR||'data','timeseries'),streams:db.sensorStreams});const robotGateway=new RobotGateway({commands:db.robotCommands,cells:db.robotCells});const notifications=new NotificationService({notifications:db.notifications});const engineMock='let d="";process.stdin.on("data",c=>d+=c).on("end",()=>{const r=JSON.parse(d);process.stdout.write(JSON.stringify({protocol:"autoforge-engine",version:"1.0",requestId:r.id,status:"succeeded",metrics:{mode:"mock",action:r.action},artifacts:[]}))})';const workerPath=name=>path.join(path.dirname(fileURLToPath(import.meta.url)),name);const sandbox=new SandboxRunner().register('diagnostic',process.execPath,['-e','process.stdout.write(JSON.stringify({ok:true,args:process.argv.slice(1)}))']).register('engine-mock',process.execPath,['-e',engineMock]).register('vehicle-cad',process.execPath,[workerPath('vehicleCadWorker.js')]).register('vehicle-simulation',process.execPath,[workerPath('vehicleSimulationWorker.js')]);if(process.env.AUTOFORGE_FREECAD_BIN) sandbox.register('freecad',process.env.AUTOFORGE_FREECAD_BIN);if(process.env.AUTOFORGE_OPENFOAM_BIN) sandbox.register('openfoam',process.env.AUTOFORGE_OPENFOAM_BIN);
const adapters=new AdapterRegistry();const queue=new JobQueue({jobs:db.jobs,events:db.jobEvents,concurrency:2,onChange:()=>persist(db)});
const generateCad=async(design,actor,organizationId)=>{const request=createEngineRequest({engine:'autoforge.parametric-cad',action:'vehicle.generate',projectId:design.projectId,designId:design.id,input:{parameters:design.parameters}}),result=await executeEngine({sandbox,artifactStore:artifacts,command:'vehicle-cad',request,actor,organizationId});Object.assign(result.execution,{projectId:design.projectId,designId:design.id});db.engineExecutions.unshift(result.execution);return{execution:result.execution,artifacts:result.execution.artifactIds.map(id=>artifacts.find(id))}};
const runSimulation=async(design,type,options,actor,organizationId)=>{const request=createEngineRequest({engine:'autoforge.reduced-order-physics',action:`simulate.${type}`,projectId:design.projectId,designId:design.id,input:{parameters:design.parameters,metrics:design.metrics},options}),engine=await executeEngine({sandbox,artifactStore:artifacts,command:'vehicle-simulation',request,actor,organizationId});db.engineExecutions.unshift(engine.execution);if(engine.execution.status!=='succeeded')throw Object.assign(new Error('simulation_failed'),{code:'simulation_failed',details:engine.execution.error});const simulation={id:`SIM-${randomUUID().slice(0,8)}`,projectId:design.projectId,designId:design.id,type,name:`${type} reduced-order physics`,status:'complete',progress:100,fidelity:engine.execution.metrics.fidelity,modelVersion:engine.execution.metrics.modelVersion,result:engine.execution.metrics.result,assumptions:engine.execution.metrics.assumptions,artifactIds:engine.execution.artifactIds,engineExecutionId:engine.execution.id,completedAt:now()};db.simulations.unshift(simulation);synchronizeProjectState(db,design.projectId,design.id,{actor});return{simulation,execution:engine.execution,artifacts:engine.execution.artifactIds.map(id=>artifacts.find(id))}};
const compareRequirement=(actual,operator,target)=>operator==='≤'?actual<=target:operator==='<'?actual<target:operator==='≥'?actual>=target:operator==='>'?actual>target:operator==='='?actual===target:false;
const verifyWorkflowRequirements=(design,{cad,simulations,manufacturing},payload)=>{const byType=Object.fromEntries(simulations.map(x=>[x.simulation?.type,x.simulation]).filter(x=>x[0])),results=[],failedCategories=[];for(const requirement of activeRequirements(db,design.projectId)){let actual,evidenceId;if(requirement.category==='dimension'&&/(전장|length)/i.test(requirement.title)){actual=Number(design.parameters.length||3990);evidenceId=cad?.execution?.id}else if(requirement.category==='package'&&/(인승|seat|승객|좌석)/i.test(requirement.title)){actual=Number(design.parameters.seats||4);evidenceId=byType.structure?.id}else if(requirement.category==='performance'&&/(주행거리|range)/i.test(requirement.title)){actual=Number(design.metrics.range);evidenceId=byType.range?.id}else if(requirement.category==='cost'){actual=requirement.unit?.includes('M')?Number(manufacturing?.cost?.total||0)/1_000_000:Number(manufacturing?.cost?.total||0);evidenceId=manufacturing?.id}else if(requirement.category==='aero'){actual=Number(design.metrics.cd);evidenceId=byType.aero?.id}const passed=Number.isFinite(actual)&&Boolean(evidenceId)&&compareRequirement(actual,requirement.operator,Number(requirement.target));if(!passed)failedCategories.push(requirement.category);if(evidenceId){const record=verifyRequirement(db,requirement.id,{status:passed?'pass':'fail',evidenceId,actor:payload.actor});requirement.actual=actual;results.push(record.verification)}}return{allPassed:results.length===activeRequirements(db,design.projectId).length&&results.every(x=>x.status==='pass'),verificationIds:results.map(x=>x.id),failedCategories:[...new Set(failedCategories)]}};
registerWorkflowHandlers(queue,adapters,db,{generateCad:(design,payload)=>generateCad(design,payload.actor,payload.organizationId),runSimulation:(design,type,payload)=>runSimulation(design,type,{},payload.actor,payload.organizationId),evaluateManufacturing:(design,payload)=>{const project=db.projects.find(x=>x.id===design.projectId),bom=projectBom(db,design.projectId),suppliers=organizationSuppliers(db,project.organizationId),evaluation=evaluateManufacturing({projectId:design.projectId,designId:design.id,bom,suppliers,parameters:design.parameters,targetCost:30000000});evaluation.bomRevision=bomSummary(db,design.projectId).activeRevision;db.manufacturingEvaluations.unshift(evaluation);synchronizeProjectState(db,design.projectId,design.id,{actor:payload.actor});return evaluation},verifyRequirements:verifyWorkflowRequirements});queue.start();
const mcp=new McpGateway({execute:async(name,args,actor)=>{
  const project=id=>{if(!canAccessProject(db,actor,id)){const error=new Error('project_not_found');error.code='project_not_found';throw error}}
  if(name==='autoforge_project_list')return db.projects.filter(x=>x.organizationId===actor.organizationId);
  if(name==='autoforge_requirement_refine'){project(args.projectId);const result=refineRequirements(args.text,args.projectId);result.conflicts=detectConflicts([...db.requirements.filter(x=>x.projectId===args.projectId),...result.requirements]);return result}
  if(name==='autoforge_requirement_draft'){project(args.projectId);return createRequirementDrafts(db,{projectId:args.projectId,text:args.text,actor:actor.id})}
  if(name==='autoforge_design_estimate')return estimateVehicle(args);
  if(name==='autoforge_cad_generate'){project(args.projectId);const design=db.designs.find(x=>x.id===args.designId&&x.projectId===args.projectId);if(!design){const error=new Error('design_not_found');error.code='design_not_found';throw error}return generateCad(design,actor.id,actor.organizationId)}
  if(name==='autoforge_simulation_run'){project(args.projectId);const design=db.designs.find(x=>x.id===args.designId&&x.projectId===args.projectId);if(!design){const error=new Error('design_not_found');error.code='design_not_found';throw error}return runSimulation(design,args.type,args.options,actor.id,actor.organizationId)}
  if(name==='autoforge_optimize'){project(args.projectId);const design=db.designs.find(x=>x.id===args.designId&&x.projectId===args.projectId);if(!design){const error=new Error('design_not_found');error.code='design_not_found';throw error}const run=optimizeDesign({projectId:args.projectId,parentDesign:design,sampleSize:args.sampleSize,seed:args.seed,weights:args.weights});run.createdBy=actor.id;run.organizationId=actor.organizationId;db.optimizationRuns.unshift(run);return run}
  if(name==='autoforge_workflow_start'){project(args.projectId);return startDesignWorkflow(queue,db,{...args,actor:actor.id,organizationId:actor.organizationId})}
  if(name==='autoforge_run_resume'){const source=db.runs.find(x=>x.id===args.runId);if(!source){const error=new Error('run_not_found');error.code='run_not_found';throw error}project(source.projectId);return resumeDesignWorkflow(queue,db,args.runId,{parameters:args.parameters,reason:args.reason,actor:actor.id,organizationId:actor.organizationId})}
  if(name==='autoforge_run_get'){const run=db.runs.find(x=>x.id===args.runId);if(!run||!canAccessProject(db,actor,run.projectId)){const error=new Error('run_not_found');error.code='run_not_found';throw error}return syncRun(run,db.jobs)}
  if(name==='autoforge_knowledge_graph'){project(args.projectId);return buildKnowledgeGraph(db,args.projectId)}
  if(name==='autoforge_release_assess'){project(args.projectId);return assessRelease(db,args.projectId,args.designId)}
  if(name==='autoforge_robot_command'){project(args.projectId);const approval=db.approvals.find(x=>x.id===args.approvalId&&x.projectId===args.projectId&&x.grade==='S4'&&x.status==='approved');return robotGateway.submit({...args,approval,actor:actor.id})}
  const error=new Error('tool_not_implemented');error.code='tool_not_implemented';throw error;
}});
