const mcpOrigins=(process.env.AUTOFORGE_MCP_ORIGINS||'').split(',').map(x=>x.trim()).filter(Boolean);
app.all('/mcp',async(req,res,next)=>{
  if(!req.actor.authenticated)return res.status(401).json({jsonrpc:'2.0',id:null,error:{code:-32000,message:'Authentication required'}});
  if(!validateMcpOrigin(req.header('origin'),{allowedOrigins:mcpOrigins,host:req.get('host')}))return res.status(403).json({jsonrpc:'2.0',id:null,error:{code:-32000,message:'Origin not allowed'}});
  if(req.method==='GET')return res.status(405).set('Allow','POST, DELETE').end();
  if(req.method==='DELETE'){const ok=mcp.terminate(req.header('mcp-session-id'),req.actor);return res.status(ok?204:404).end()}
  if(req.method!=='POST')return res.status(405).set('Allow','POST, DELETE').end();
  const version=req.header('mcp-protocol-version');if(version&&version!==MCP_PROTOCOL_VERSION)return res.status(400).json({jsonrpc:'2.0',id:null,error:{code:-32003,message:'Unsupported protocol version',data:{supported:[MCP_PROTOCOL_VERSION]}}});
  const messages=Array.isArray(req.body)?req.body:[req.body],responses=[];let sessionId=req.header('mcp-session-id');
  for(const message of messages){const response=await mcp.handle(message,{actor:req.actor,sessionId});if(response?.sessionId){sessionId=response.sessionId;delete response.sessionId;res.setHeader('Mcp-Session-Id',sessionId)}if(response)responses.push(response);db.audit.unshift({id:randomUUID(),at:now(),actor:req.actor.id,role:req.actor.role,method:'MCP',path:message?.method||'invalid',tool:message?.params?.name,status:response?.error?'error':'ok',requestId:req.requestId})}
  persist(db);if(!responses.length)return res.status(202).end();res.type('application/json').json(Array.isArray(req.body)?responses:responses[0]);
});
