app.get('/api/runs/:id/stream',(req,res)=>{
  const run=db.runs.find(x=>x.id===req.params.id);if(!run||!canAccessProject(db,req.actor,run.projectId))return res.status(404).json({error:'run_not_found'});
  res.setHeader('Content-Type','text/event-stream');res.setHeader('Cache-Control','no-cache');res.setHeader('Connection','keep-alive');res.flushHeaders?.();
  const send=(event,name='job')=>{res.write(`event: ${name}\n`);res.write(`data: ${JSON.stringify(event)}\n\n`)};
  send(syncRun(run,db.jobs),'snapshot');for(const event of db.jobEvents.filter(x=>x.runId===run.id).slice(0,50).reverse())send(event);
  const unsubscribe=queue.subscribe(event=>{if(event.runId!==run.id)return;send(event);const current=syncRun(run,db.jobs);if(['complete','failed','blocked','needs_review'].includes(current.status))send(current,'run')});
  const keepalive=setInterval(()=>res.write(': keepalive\n\n'),15000);req.on('close',()=>{clearInterval(keepalive);unsubscribe()});
});
