app.post('/api/approvals',requirePermission('approval.create'),(req,res)=>{if(!canAccessProject(db,req.actor,req.body.projectId))return res.status(404).json({error:'project_not_found'});try{const approval=createApprovalRequest({...req.body,organizationId:req.actor.organizationId,requester:req.actor.id});db.approvals.unshift(approval);if(approval.status==='pending')notifications.create({organizationId:req.actor.organizationId,roles:approval.grade==='S4'?['site_manager']:approval.grade==='S3'?['reviewer','safety_officer']:['reviewer','safety_officer','site_manager'],type:'approval_requested',title:`${approval.grade} 승인 요청`,message:approval.title,severity:['S3','S4','S5'].includes(approval.grade)?'critical':'info',link:'/approvals',data:{approvalId:approval.id}});res.status(201).json({...approval,progress:approvalProgress(approval)})}catch(error){res.status(400).json({error:error.message})}});
app.patch('/api/approvals/:id',requirePermission('approval.review'),(req,res)=>{const approval=db.approvals.find(x=>x.id===req.params.id);if(!approval||!canAccessProject(db,req.actor,approval.projectId))return res.status(404).json({error:'approval_not_found'});try{decideApproval(approval,{actorId:req.actor.id,role:req.actor.role,decision:req.body.status||req.body.decision,comment:req.body.comment});synchronizeProjectState(db,approval.projectId,approval.targetId,{actor:req.actor.id});notifications.create({organizationId:approval.organizationId,userId:approval.requester,type:'approval_decision',title:`승인 상태: ${approval.status}`,message:approval.title,severity:approval.status==='rejected'?'critical':'info',data:{approvalId:approval.id}});res.json({...approval,progress:approvalProgress(approval)})}catch(error){res.status(409).json({error:error.code||'approval_failed',message:error.message})}});
app.get('/api/notifications',(req,res)=>res.json(notifications.list(req.actor,{unreadOnly:req.query.unread==='true'})));
app.patch('/api/notifications/:id/read',(req,res)=>{const item=notifications.markRead(req.params.id,req.actor);if(!item)return res.status(404).json({error:'notification_not_found'});res.json(item)});
app.post('/api/notifications/read-all',(req,res)=>res.json({updated:notifications.markAllRead(req.actor)}));
app.get('/api/improvements',(req,res)=>res.json(db.improvementRuns.filter(x=>x.organizationId===req.actor.organizationId)));
app.post('/api/improvements',requirePermission('improvement.create'),(req,res)=>{const artifact=artifacts.find(req.body.artifactId);if(!artifact||artifact.organizationId!==req.actor.organizationId)return res.status(404).json({error:'artifact_not_found'});try{const run=createImprovement({...req.body,organizationId:req.actor.organizationId,author:req.actor.id});db.improvementRuns.unshift(run);notifications.create({organizationId:req.actor.organizationId,roles:['reviewer'],type:'improvement_review',title:'플랫폼 변경 리뷰 요청',message:run.title,severity:'info',data:{improvementId:run.id}});res.status(201).json(run)}catch(error){res.status(400).json({error:error.code||error.message})}});
app.post('/api/improvements/:id/advance',requirePermission('improvement.manage'),(req,res)=>{const run=db.improvementRuns.find(x=>x.id===req.params.id&&x.organizationId===req.actor.organizationId);if(!run)return res.status(404).json({error:'improvement_not_found'});const approval=req.body.approvalId?db.approvals.find(x=>x.id===req.body.approvalId):null;try{advanceImprovement(run,{action:req.body.action,actor:req.actor.id,role:req.actor.role,evidence:req.body.evidence||{},approval});if(run.status==='approval_pending')notifications.create({organizationId:req.actor.organizationId,roles:['reviewer','safety_officer','site_manager'],type:'platform_approval',title:`${run.riskGrade} 플랫폼 변경 승인 필요`,message:run.title,severity:'warning',data:{improvementId:run.id}});res.json(run)}catch(error){res.status(409).json({error:error.code||'pipeline_failed',details:error.details})}});
app.post('/api/improvements/:id/canary',requirePermission('improvement.manage'),(req,res)=>{const run=db.improvementRuns.find(x=>x.id===req.params.id&&x.organizationId===req.actor.organizationId);if(!run)return res.status(404).json({error:'improvement_not_found'});try{res.json(startCanary(run,{actor:req.actor.id,percent:req.body.percent,baseline:req.body.baseline}))}catch(error){res.status(409).json({error:error.code})}});
app.post('/api/improvements/:id/observe',requirePermission('improvement.manage'),(req,res)=>{const run=db.improvementRuns.find(x=>x.id===req.params.id&&x.organizationId===req.actor.organizationId);if(!run)return res.status(404).json({error:'improvement_not_found'});try{observeCanary(run,{actor:req.actor.id,metrics:req.body.metrics});if(run.status==='rolled_back')notifications.create({organizationId:req.actor.organizationId,roles:['admin','reviewer'],type:'automatic_rollback',title:'카나리 성능 저하 · 자동 롤백',message:run.title,severity:'critical',data:{improvementId:run.id}});if(run.status==='deployed')db.platformReleases.unshift({id:randomUUID(),improvementId:run.id,artifactId:run.artifactId,status:'active',deployedAt:run.deployedAt});res.json(run)}catch(error){res.status(409).json({error:error.code})}});
app.post('/api/improvements/:id/rollback',requirePermission('improvement.manage'),(req,res)=>{const run=db.improvementRuns.find(x=>x.id===req.params.id&&x.organizationId===req.actor.organizationId);if(!run)return res.status(404).json({error:'improvement_not_found'});try{res.json(rollbackImprovement(run,{actor:req.actor.id,reason:req.body.reason}))}catch(error){res.status(409).json({error:error.code})}});
app.get('/api/platform/releases',(req,res)=>res.json(db.platformReleases.filter(r=>db.improvementRuns.find(x=>x.id===r.improvementId)?.organizationId===req.actor.organizationId)));
app.get('/api/compliance/assessments',(req,res)=>res.json(db.complianceAssessments.filter(x=>canAccessProject(db,req.actor,x.projectId)&&(!req.query.projectId||x.projectId===req.query.projectId)&&(!req.query.designId||x.designId===req.query.designId))));
app.post('/api/compliance/assess',requirePermission('safety.execute'),(req,res)=>{if(!canAccessProject(db,req.actor,req.body.projectId))return res.status(404).json({error:'project_not_found'});try{res.status(201).json(createComplianceAssessment(db,{projectId:req.body.projectId,designId:req.body.designId},{actor:req.actor.id}))}catch(error){res.status(404).json({error:error.code||'compliance_assessment_failed'})}});
app.get('/api/projects/:id/release-assessment',requireProjectAccess(db),(req,res)=>res.json(assessRelease(db,req.params.id,req.query.designId||'AF-C04')));
app.get('/api/design-releases',(req,res)=>res.json(db.designReleases.filter(r=>canAccessProject(db,req.actor,r.projectId))));
app.post('/api/projects/:id/releases',requirePermission('transition.execute'),requireProjectAccess(db),(req,res)=>{try{const release=createRelease(db,{projectId:req.params.id,designId:req.body.designId,artifactStore:artifacts,actor:req.actor.id});synchronizeProjectState(db,req.params.id,req.body.designId,{actor:req.actor.id});res.status(201).json(release)}catch(error){res.status(409).json({error:error.code||'release_failed',missing:error.missing})}});
app.get('/api/audit',requirePermission('safety.execute'),(req,res)=>res.json(db.audit.slice(0,Number(req.query.limit)||100)));
app.get('/api/reports/:projectId',requireProjectAccess(db,'projectId'),(req,res)=>{const graph={project:db.projects.find(x=>x.id===req.params.projectId),requirements:db.requirements.filter(x=>x.projectId===req.params.projectId),designs:db.designs.filter(x=>x.projectId===req.params.projectId),simulations:db.simulations.filter(x=>x.projectId===req.params.projectId),bom:projectBom(db,req.params.projectId),bomSummary:bomSummary(db,req.params.projectId),generatedAt:now()};res.setHeader('Content-Disposition','attachment; filename="autoforge-report.json"');res.json(graph)});
app.use('/api',apiErrorHandler);
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');app.use(express.static(path.join(root,'dist')));app.use((req,res,next)=>req.path.startsWith('/api')?next():res.sendFile(path.join(root,'dist','index.html')));
const server=app.listen(port,()=>console.log(`AutoForge Core API running on http://localhost:${port}`));
const shutdown=signal=>{console.log(`${signal}: draining AutoForge Core`);queue.stop();persist(db);server.close(()=>process.exit(0));setTimeout(()=>process.exit(1),10000).unref()};
process.once('SIGTERM',()=>shutdown('SIGTERM'));process.once('SIGINT',()=>shutdown('SIGINT'));
